import React, { useState, useRef, useEffect, KeyboardEvent, ClipboardEvent } from 'react';

interface EnhancedInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  onToggleDebug?: () => void;
  placeholder?: string;
  disabled?: boolean;
  history: string[];  // Input history array
  maxLength?: number;
}

// Paste deduplication settings (matching TUI)
const PASTE_WINDOW_MS = 200;  // Merge paste events within 200ms
const MIN_SINGLE_LINE_LENGTH = 50;  // Threshold for multi-line confirmation
const COLLAPSE_LINE_THRESHOLD = 3;  // Lines threshold for collapsing (matching TUI)

export function EnhancedInput({
  value,
  onChange,
  onSubmit,
  onToggleDebug,
  placeholder = 'Type a message...',
  disabled = false,
  history,
  maxLength = 2000,
}: EnhancedInputProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [historyIndex, setHistoryIndex] = useState<number | null>(null);
  const [draft, setDraft] = useState<string>('');  // Saves current input when entering history
  const [isMultilinePaste, setIsMultilinePaste] = useState(false);  // Multi-line paste confirmation mode
  const [pendingPaste, setPendingPaste] = useState<string>('');  // Pending paste content
  const [pasteConfirmCount, setPasteConfirmCount] = useState(0);  // Enter press count for confirmation
  const [lastPasteTime, setLastPasteTime] = useState<number>(0);  // Last paste timestamp
  const [pasteBuffer, setPasteBuffer] = useState<string>('');  // Buffer for paste deduplication

  // Collapsed state (matching TUI input_collapsed)
  const [isCollapsed, setIsCollapsed] = useState(true);  // Default: collapsed when > 3 lines
  const [multilineConfirmSend, setMultilineConfirmSend] = useState(false);  // Confirmation state

  // Calculate line count
  const lineCount = value.split('\n').length;
  const shouldCollapse = lineCount > COLLAPSE_LINE_THRESHOLD && isCollapsed;

  // Auto-resize textarea based on content
  useEffect(() => {
    const textarea = textareaRef.current;
    if (textarea && !isCollapsed) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.min(textarea.scrollHeight, 200)}px`;
    }
  }, [value, isCollapsed]);

  // Handle paste with deduplication (matching TUI behavior)
  const handlePaste = (e: ClipboardEvent<HTMLTextAreaElement>) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData('text');
    const now = Date.now();

    // Deduplication: merge paste events within window
    if (now - lastPasteTime < PASTE_WINDOW_MS && pasteBuffer) {
      // Append to buffer (dedup logic)
      const merged = pasteBuffer + pastedText;
      setPasteBuffer(merged);
      onChange(value + merged);
    } else {
      // New paste sequence
      setPasteBuffer(pastedText);
      setLastPasteTime(now);
      onChange(value + pastedText);
    }

    // Check if pasted content has multiple lines (needs confirmation)
    const lines = pastedText.split('\n').length;
    const hasMultipleLines = lines > 1 || pastedText.length > MIN_SINGLE_LINE_LENGTH;

    if (hasMultipleLines) {
      setIsMultilinePaste(true);
      setIsCollapsed(true);  // Collapse after paste (matching TUI)
      setPendingPaste(pastedText);
      setPasteConfirmCount(0);
      setMultilineConfirmSend(true);  // Mark for confirmation
    }
  };

  // Clear paste buffer after timeout
  useEffect(() => {
    if (pasteBuffer) {
      const timer = setTimeout(() => {
        setPasteBuffer('');
      }, PASTE_WINDOW_MS + 100);
      return () => clearTimeout(timer);
    }
  }, [pasteBuffer]);

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    // Ctrl/Cmd+D - toggle debug panel
    if ((e.ctrlKey || e.metaKey) && e.key === 'd') {
      e.preventDefault();
      if (onToggleDebug) onToggleDebug();
      return;
    }

    // Ctrl/Cmd+K - clear input
    if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
      e.preventDefault();
      onChange('');
      setHistoryIndex(null);
      setIsCollapsed(true);
      setMultilineConfirmSend(false);
      return;
    }

    // Multi-line paste confirmation mode (matching TUI)
    if (isMultilinePaste || multilineConfirmSend) {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();

        // Check if collapsed - first Enter should expand
        if (shouldCollapse) {
          setIsCollapsed(false);
          setPasteConfirmCount(1);
          return;
        }

        const newCount = pasteConfirmCount + 1;
        setPasteConfirmCount(newCount);

        if (newCount >= 2) {
          // Two Enter presses to confirm (matching TUI)
          setIsMultilinePaste(false);
          setPendingPaste('');
          setPasteConfirmCount(0);
          setMultilineConfirmSend(false);
          setIsCollapsed(false);
          onSubmit();
        }
        return;
      }
      if (e.key === 'Escape') {
        // Cancel multi-line paste/send
        e.preventDefault();
        setIsMultilinePaste(false);
        setPendingPaste('');
        setPasteConfirmCount(0);
        setMultilineConfirmSend(false);
        return;
      }
      // Allow normal editing in expanded mode
      if (!shouldCollapse) return;
    }

    // Shift+Enter - insert newline
    if (e.key === 'Enter' && e.shiftKey) {
      e.preventDefault();
      const textarea = textareaRef.current;
      if (textarea) {
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;
        const newValue = value.substring(0, start) + '\n' + value.substring(end);
        onChange(newValue);
        setIsCollapsed(false);  // Expand when manually adding newlines (matching TUI)
        setMultilineConfirmSend(false);  // Reset confirmation state

        // Restore cursor position after newline
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 1;
        }, 0);
      }
      return;
    }

    // Enter - send message
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();

      // Check if has multiple lines and needs confirmation
      if (lineCount > 1 && !multilineConfirmSend) {
        // First Enter on multiline: require confirmation (matching TUI)
        setMultilineConfirmSend(true);
        setPasteConfirmCount(1);
        return;
      }

      // Second Enter or single line: send
      if (value.trim()) {
        setMultilineConfirmSend(false);
        setIsCollapsed(true);
        onSubmit();
      }
      return;
    }

    // Up arrow - navigate history backwards (only at start of input)
    if (e.key === 'ArrowUp' && !e.shiftKey && !e.metaKey && !e.ctrlKey) {
      const textarea = textareaRef.current;
      const atStart = textarea?.selectionStart === 0;

      if (atStart && history.length > 0) {
        e.preventDefault();
        if (historyIndex === null) {
          // Save current input before entering history
          setDraft(value);
          setHistoryIndex(history.length - 1);
          onChange(history[history.length - 1]);
        } else if (historyIndex > 0) {
          setHistoryIndex(historyIndex - 1);
          onChange(history[historyIndex - 1]);
        }
      }
      return;
    }

    // Down arrow - navigate history forwards (only at end of input)
    if (e.key === 'ArrowDown' && !e.shiftKey && !e.metaKey && !e.ctrlKey) {
      const textarea = textareaRef.current;
      const atEnd = textarea?.selectionStart === value.length;

      if (atEnd && historyIndex !== null) {
        e.preventDefault();
        if (historyIndex < history.length - 1) {
          setHistoryIndex(historyIndex + 1);
          onChange(history[historyIndex + 1]);
        } else {
          // Exit history mode, restore draft
          setHistoryIndex(null);
          onChange(draft);
        }
      }
      return;
    }

    // Escape - clear input or cancel
    if (e.key === 'Escape') {
      e.preventDefault();
      if (multilineConfirmSend) {
        // Cancel multiline send confirmation
        setMultilineConfirmSend(false);
        setPasteConfirmCount(0);
      } else if (value) {
        // Clear input
        onChange('');
        setHistoryIndex(null);
        setIsCollapsed(true);
      }
      return;
    }
  };

  // Toggle collapsed state
  const toggleCollapse = () => {
    setIsCollapsed(!isCollapsed);
    if (!isCollapsed && textareaRef.current) {
      setTimeout(() => textareaRef.current?.focus(), 0);
    }
  };

  // Render collapsed preview
  const renderCollapsedPreview = () => {
    const lines = value.split('\n');
    const previewLines = lines.slice(0, COLLAPSE_LINE_THRESHOLD);
    const remainingLines = lines.length - COLLAPSE_LINE_THRESHOLD;

    return (
      <div className="relative">
        <pre className="text-sm font-mono whitespace-pre-wrap break-words p-2 bg-muted/30 rounded">
          {previewLines.join('\n')}
          {remainingLines > 0 && (
            <span className="text-muted-foreground text-xs">
              {'\n'}... ({remainingLines} more lines)
            </span>
          )}
        </pre>
        <button
          onClick={toggleCollapse}
          className="absolute top-1 right-1 px-1.5 py-0.5 text-xs text-muted-foreground hover:text-foreground bg-muted/80 rounded"
          title="展开"
        >
          ▼
        </button>
      </div>
    );
  };

  return (
    <div className="relative">
      {/* Multi-line confirmation warning */}
      {(isMultilinePaste || multilineConfirmSend) && (
        <div className="absolute -top-8 left-0 right-0 px-3 py-1.5 bg-yellow-500/10 border border-yellow-500/30 rounded text-xs text-yellow-600 dark:text-yellow-400 flex items-center justify-between">
          <span>
            {shouldCollapse
              ? '⚠️ 多行内容已折叠，按 Enter 展开'
              : pasteConfirmCount === 0
                ? '⚠️ 多行内容，按 Enter 再次确认发送'
                : `⚠️ 已按 ${pasteConfirmCount} 次 Enter，再按 ${2 - pasteConfirmCount} 次发送`
            }
          </span>
          <button
            onClick={() => {
              setIsMultilinePaste(false);
              setMultilineConfirmSend(false);
              setPasteConfirmCount(0);
            }}
            className="text-xs px-1 hover:bg-yellow-500/20 rounded"
          >
            ✕ 取消
          </button>
        </div>
      )}

      {/* Collapsed preview or expanded textarea */}
      {shouldCollapse ? (
        renderCollapsedPreview()
      ) : (
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => {
            onChange(e.target.value);
            setHistoryIndex(null);
            // Auto-collapse if becomes > threshold lines and not focused
            const newLines = e.target.value.split('\n').length;
            if (newLines <= COLLAPSE_LINE_THRESHOLD) {
              setIsCollapsed(true);
            }
          }}
          onKeyDown={handleKeyDown}
          onPaste={handlePaste}
          placeholder={placeholder}
          disabled={disabled}
          maxLength={maxLength}
          className="w-full px-3 py-2 bg-background border border-input rounded-lg text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary/50 disabled:opacity-50 disabled:cursor-not-allowed"
          rows={1}
          style={{ minHeight: '40px' }}
        />
      )}

      {/* Line count indicator */}
      {lineCount > 1 && !shouldCollapse && (
        <div className="absolute bottom-1 right-2 text-xs text-muted-foreground">
          {lineCount} lines
        </div>
      )}

      {/* Collapse/expand button (when not in collapsed mode) */}
      {!shouldCollapse && lineCount > COLLAPSE_LINE_THRESHOLD && (
        <button
          onClick={toggleCollapse}
          className="absolute top-1 right-1 px-1.5 py-0.5 text-xs text-muted-foreground hover:text-foreground bg-muted/80 rounded"
          title="折叠"
        >
          ▲
        </button>
      )}
    </div>
  );
}